layers.vertex:
attribute vec3 aO; attribute float aYaw; attribute vec4 aS; uniform float uTime; varying vec2 vF; varying float vAge, vFrom, vTo;
    void main(){
      if (aS.w < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float age = uTime - aS.z, S = age < .24 ? 1.45 : .98;
      vec2 l = position.xz*S;                           // local metres, -z = forward
      float c = cos(aYaw), s = sin(aYaw);
      vec2 w = vec2(c*l.x + s*l.y, -s*l.x + c*l.y);
      vF = vec2(l.x, -l.y); vAge = age; vFrom = aS.x; vTo = aS.y;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(w.x, .03, w.y), 1.);
    }

layers.fragment:
uniform float uTime; uniform vec3 uCW, uCT; varying vec2 vF; varying float vAge, vFrom, vTo; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    // soft stroke: bright thin core + wide feathered halo (no hard edges, no flat facets)
    float stroke(float d, float w){ return exp(-(d*d)/(w*w)) + .28*exp(-(d*d)/(w*w*22.)); }
    float lineCore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec2 p = vF; float r = length(p), ang = atan(p.x, p.y), a = abs(ang);
      float k = clamp(vAge/.14, 0., 1.), m = mix(vFrom, vTo, k*k*(3.-2.*k));
      vec3 col = mix(uCW, uCT, m);
      // calligraphic crescents: taper to hair-fine tips, energy drifting slowly along the arc
      float t = clamp((a - .42)/2.25, 0., 1.), taper = pow(sin(3.14159*t), .7);
      float flow = .78 + .22*sin(a*9. - uTime*2.2 + sign(ang)*1.3);
      float arcA = stroke(r - .66, .006 + .016*taper) * step(.42, a) * step(a, 2.67) * taper * flow;
      float tb = clamp((a - .75)/1.6, 0., 1.), taperB = pow(sin(3.14159*tb), 1.2);
      float arcB = stroke(r - .57, .004 + .006*taperB) * step(.75, a) * step(a, 2.35) * taperB * .55;
      float core = lineCore(r - .66, .004 + .006*taper) * step(.42, a) * step(a, 2.67) * taper;
      // four glints where the icon has crystal shards: soft points that breathe
      float gl = 0.;
      for (int i=0;i<4;i++){
        float g = (i < 2 ? 1.15 : 2.05) * (mod(float(i),2.) < .5 ? 1. : -1.);
        vec2 c = .8*vec2(sin(g), cos(g)); float d2 = dot(p-c, p-c);
        gl += (exp(-d2/.00012) + .25*exp(-d2/.0025)) * (.7 + .3*sin(uTime*1.7 + float(i)*1.9));
      }
      // emblem in the back opening, drawn as fine line-art with a faint fill
      vec2 e = p - vec2(0., -.76);
      float bd = abs(e.x)/.05 + abs(e.y)/.19 - 1.;
      float blade = stroke(bd*.05, .006) + .12*step(bd, 0.);
      float top = .1, tip = -.13, hw = .1;
      float wy = e.y > 0. ? hw : hw*clamp((e.y - tip)/(0. - tip), 0., 1.);
      float sd = max(abs(e.x) - wy, max(e.y - top, tip - e.y));
      float shield = stroke(sd, .006) + .12*step(sd, 0.) + .5*lineCore(sd + .028, .004)*step(sd, 0.);
      float emblem = mix(blade, shield, m);
      // warm ground light under the Fighter: the marker reads as light on stone, not a sticker
      float pool = exp(-r*r*4.5)*.16 + exp(-r*r*1.2)*.05;
      float body = arcA + arcB + gl*.9 + emblem*.9 + pool;
      // switch: 2-frame bloom peak, then a feathered ring with a thin leading edge
      float peak = vAge < .033 ? 2.2 : 1. + 1.1*exp(-(vAge-.033)*16.);
      float rr = mix(.4, 1.35, eox(clamp(vAge/.2, 0., 1.))), fade = 1. - clamp(vAge/.24, 0., 1.);
      float ring = (lineCore(r - rr, .012)*1.3 + exp(-pow((r-rr)/.09, 2.))*.35) * fade*fade * step(0., vAge);
      float disk = exp(-r*r*6.) * (vAge < .033 ? 1.2 : 0.);
      float lum = body*(vAge < .26 ? peak : 1.) + ring + disk;
      vec3 hot = mix(col, vec3(1., .93, .9), .55);             // near-white core, stance-tinted halo
      vec3 outc = col*lum + hot*(core*.9 + ring*.25)*(vAge < .26 ? peak : 1.);
      float S = vAge < .24 ? 1.45 : .98;
      outc *= smoothstep(S, S*.78, r);                            // everything fades to zero before the quad's edge — no visible square
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc*1.1, 1.);
    }

layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 1.05){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 4.0; vP = position.xy*S; vU = u; vK = aK;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .035, -position.y*S), 1.);
    }

layers.fragment:
uniform vec3 uCW, uCT; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){
      vec2 p = vP; float r = length(p), a = atan(p.x, p.y), R = 3.6, u = vU - 0.15;
      vec3 col = mix(uCW, uCT, vK);
      float lum = 0., hot = 0.;
      if (u < 0.){
        // wind-up: a small gather at the Root
        float k = vU/0.15; lum += exp(-r*r*14.)*k*k*.5;
      } else {
        lum += exp(-r*r*5.)*(u < .033 ? 1.1 : .4*exp(-u*10.));      // 2-frame snap at the Root
        if (vK < .5){
          // Battlecry: three crests, the middle one strongest, slightly jagged — fast and aggressive
          for (int j=0;j<3;j++){
            float fj = float(j), uj = u - fj*.045;
            if (uj < 0.) continue;
            float rr = eox(clamp(uj/.2, 0., 1.))*R*(1. - .06*fj);
            rr += .035*abs(sin(a*9. + fj*1.3))*smoothstep(.2, 1., rr/R);
            float f = 1. - smoothstep(.12, .3, uj), wgt = fj == 1. ? 1. : .55;
            float w = (.012 + .03*wgt)*(1. - .5*clamp(uj/.3, 0., 1.));
            lum += exp(-pow(abs(r - rr)/w, 2.4))*f*wgt*1.1; hot += lcore(r - rr, w*.3)*f*wgt*.5;
          }
        } else {
          // Challenge: one steady pulse that settles and stays anchored on the area edge
          float rr = eox(clamp(u/.22, 0., 1.))*R, f = 1. - smoothstep(.15, .3, u);
          lum += exp(-pow(abs(r - rr)/.02, 2.4))*f*.9;
          float hold = smoothstep(.16, .24, u)*(1. - smoothstep(.55, .9, u));   // the rim is the last thing to go
          float ring = exp(-pow(abs(r - R)/.016, 2.4));
          float tick = 0.;
          for (int i=0;i<16;i++){
            float th = float(i)*.3927; vec2 d = vec2(sin(th), cos(th));
            float along = dot(p, d), off = abs(p.x*d.y - p.y*d.x);
            tick += exp(-pow(off/.012, 2.))*smoothstep(R - .32, R - .22, along)*smoothstep(R - .04, R - .12, along);
          }
          lum += (ring*.95 + tick*.55)*hold; hot += lcore(r - R, .005)*hold*.5;
        }
      }
      vec3 outc = col*lum + mix(col, vec3(1., .96, .95), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

