    void main(){
      vec2 p = vP; float r = length(p), t = vU/.16, f = pow(1. - t, 1.6);
      float R = .03 + .22*(1. - pow(1. - t, 3.)), w = .006 + .008*(1. - t);
      vec3 col = mix(uCW, uCT, vK);
      float lum = exp(-pow(abs(r - R)/w, 2.4))*f*.45 + exp(-r*r*300.)*f*.4;
      vec3 outc = col*lum + mix(col, vec3(1.), .6)*lcore(r - R, w*.35)*f*.4;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

layers.vertex:
attribute vec3 aO; attribute float aYaw; attribute vec4 aS; uniform float uTime; varying vec2 vF; varying float vAge, vFrom, vTo;
    void main(){
      if (aS.w < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float age = uTime - aS.z, S = age < .24 ? 1.45 : .98;
      vec2 l = position.xz*S;                           // local metres, -z = forward
      float c = cos(aYaw), s = sin(aYaw);
      vec2 w = vec2(c*l.x + s*l.y, -s*l.x + c*l.y);
      vF = vec2(l.x, -l.y); vAge = age; vFrom = aS.x; vTo = aS.y;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(w.x, .03, w.y), 1.);
    }

layers.fragment:
uniform float uTime; uniform vec3 uCW, uCT; varying vec2 vF; varying float vAge, vFrom, vTo; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    // soft stroke: bright thin core + wide feathered halo (no hard edges, no flat facets)
    float stroke(float d, float w){ return exp(-(d*d)/(w*w)) + .28*exp(-(d*d)/(w*w*22.)); }
    float lineCore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec2 p = vF; float r = length(p), ang = atan(p.x, p.y), a = abs(ang);
      float k = clamp(vAge/.14, 0., 1.), m = mix(vFrom, vTo, k*k*(3.-2.*k));
      vec3 col = mix(uCW, uCT, m);
      // calligraphic crescents: taper to hair-fine tips, energy drifting slowly along the arc
      float t = clamp((a - .42)/2.25, 0., 1.), taper = pow(sin(3.14159*t), .7);
      float flow = .78 + .22*sin(a*9. - uTime*2.2 + sign(ang)*1.3);
      float arcA = stroke(r - .66, .006 + .016*taper) * step(.42, a) * step(a, 2.67) * taper * flow;
      float tb = clamp((a - .75)/1.6, 0., 1.), taperB = pow(sin(3.14159*tb), 1.2);
      float arcB = stroke(r - .57, .004 + .006*taperB) * step(.75, a) * step(a, 2.35) * taperB * .55;
      float core = lineCore(r - .66, .004 + .006*taper) * step(.42, a) * step(a, 2.67) * taper;
      // four glints where the icon has crystal shards: soft points that breathe
      float gl = 0.;
      for (int i=0;i<4;i++){
        float g = (i < 2 ? 1.15 : 2.05) * (mod(float(i),2.) < .5 ? 1. : -1.);
        vec2 c = .8*vec2(sin(g), cos(g)); float d2 = dot(p-c, p-c);
        gl += (exp(-d2/.00012) + .25*exp(-d2/.0025)) * (.7 + .3*sin(uTime*1.7 + float(i)*1.9));
      }
      // emblem in the back opening, drawn as fine line-art with a faint fill
      vec2 e = p - vec2(0., -.76);
      float bd = abs(e.x)/.05 + abs(e.y)/.19 - 1.;
      float blade = stroke(bd*.05, .006) + .12*step(bd, 0.);
      float top = .1, tip = -.13, hw = .1;
      float wy = e.y > 0. ? hw : hw*clamp((e.y - tip)/(0. - tip), 0., 1.);
      float sd = max(abs(e.x) - wy, max(e.y - top, tip - e.y));
      float shield = stroke(sd, .006) + .12*step(sd, 0.) + .5*lineCore(sd + .028, .004)*step(sd, 0.);
      float emblem = mix(blade, shield, m);
      // warm ground light under the Fighter: the marker reads as light on stone, not a sticker
      float pool = exp(-r*r*4.5)*.16 + exp(-r*r*1.2)*.05;
      float body = arcA + arcB + gl*.9 + emblem*.9 + pool;
      // switch: 2-frame bloom peak, then a feathered ring with a thin leading edge
      float peak = vAge < .033 ? 2.2 : 1. + 1.1*exp(-(vAge-.033)*16.);
      float rr = mix(.4, 1.35, eox(clamp(vAge/.2, 0., 1.))), fade = 1. - clamp(vAge/.24, 0., 1.);
      float ring = (lineCore(r - rr, .012)*1.3 + exp(-pow((r-rr)/.09, 2.))*.35) * fade*fade * step(0., vAge);
      float disk = exp(-r*r*6.) * (vAge < .033 ? 1.2 : 0.);
      float lum = body*(vAge < .26 ? peak : 1.) + ring + disk;
      vec3 hot = mix(col, vec3(1., .93, .9), .55);             // near-white core, stance-tinted halo
      vec3 outc = col*lum + hot*(core*.9 + ring*.25)*(vAge < .26 ? peak : 1.);
      float S = vAge < .24 ? 1.45 : .98;
      outc *= smoothstep(S, S*.78, r);                            // everything fades to zero before the quad's edge — no visible square
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc*1.1, 1.);
    }

layers.vertex:
attribute vec3 aO; attribute float aT, aK, aM; uniform float uTime; varying vec2 vP; varying float vAge, vK, vM;
    void main(){
      float age = uTime - aT; if (age < 0. || age > 1.21){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vAge = age; vK = aK; vM = aM;
      if (aM < .5){
        float S = 1.9, Sw = 1.15; vP = position.xy*S;                  // horizontal plane at the waist, not a ground decal
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*Sw, .95, -position.y*Sw), 1.);
      } else {
        if (age < 0.26){ gl_Position = vec4(2.,2.,2.,1.); return; }
        vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.22, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.38;
        float S = .42; mv.xy += position.xy*S; vP = position.xy*S;
        gl_Position = projectionMatrix*mv;
      }
    }

layers.fragment:
uniform vec3 uCR, uCB; varying vec2 vP; varying float vAge, vK, vM; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); } float stroke(float d, float w){ return exp(-(d*d)/(w*w)) + .28*exp(-(d*d)/(w*w*22.)); }
  float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float box(vec2 p, vec2 b){ vec2 d = abs(p) - b; return length(max(d,0.)) + min(max(d.x,d.y),0.); }
    void main(){
      vec2 p = vP; float r = length(p), ph = atan(p.y, p.x), T = 0.26;
      vec3 col = mix(uCR, uCB, vK);
      float lum = 0., hot = 0.;
      if (vM < .5){
        if (vAge < T){
          // spiral strokes sweep in across the floor and gather under the feet
          float t = vAge/T, e = t*t, R = mix(1.7, .14, e);
          for (int i=0;i<5;i++){
            float h = float(i)*1.2566 + e*2.6 + .6*(1.-vK);
            float dl = mod(h - ph, 6.28318), L = 1.3;
            if (dl < L){
              float s = dl/L, rr = R + dl*.28*(1. - e*.6), w = (.014 + .026*(1.-s))*(1. - e*.4), fall = pow(1.-s, 1.4)*(.35 + .65*t);
              lum += stroke(r - rr, w)*fall; hot += lcore(r - rr, w*.4)*fall*(1.-s);
            }
          }
          lum += exp(-r*r*18.)*t*t*1.4;
        } else {
          float u = vAge - T;
          lum += exp(-r*r*6.)*((u < .033 ? 2. : 0.) + .9*exp(-u*8.));
          for (int j=0;j<2;j++){                     // Rage: two quick heal pulses; Bulwark: one
            float uj = u - float(j)*.09;
            if (uj < 0. || (j == 1 && vK > .5)) continue;
            float rr = .15 + eox(clamp(uj/.32, 0., 1.))*1.55, f = 1. - clamp(uj/.36, 0., 1.);
            lum += (lcore(r - rr, .016)*1.2 + exp(-pow((r-rr)/.11, 2.))*.3)*f*f*(j == 0 ? 1. : .7);
            hot += lcore(r - rr, .008)*f*f*.6;
          }
        }
      } else {
        float u = vAge - T, em = 1.7*exp(-u*3.2) + .25*exp(-u*1.2);
        float cross = min(box(p, vec2(.028,.13)), box(p, vec2(.13,.028)));
        float top = .13, tip = -.16, hw = .12, wy = p.y > 0. ? hw : hw*clamp((p.y - tip)/(0. - tip), 0., 1.);
        float sd = max(abs(p.x) - wy, max(p.y - top, tip - p.y));
        float d = mix(cross, sd, vK);
        lum += (stroke(d, .006) + .14*step(d, 0.))*em + exp(-r*r*60.)*em*.3; hot += lcore(d, .004)*em*.8;
      }
      vec3 outc = col*lum + mix(col, vec3(1., .95, .92), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

layers.vertex:
attribute vec3 aO, aV; attribute vec2 aT, aM; uniform float uTime; varying vec2 vUv; varying float vF, vK;
    void main(){
      float age = uTime - aT.x; if (age < 0. || age > aT.y){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float t = age/aT.y; vec3 p;
      if (aM.x > .5) p = mix(aO, aV, t*t);
      else { float e = exp(-1.6*age); p = aO + aV*(1.-e)/1.6 + vec3(0., .18*age*age, 0.); }
      float sz = aM.x > .5 ? .07 : .065*(.5 + .5*(1.-t));
      vec4 mv = viewMatrix*vec4(p,1.); mv.xy += position.xy*sz*2.2; gl_Position = projectionMatrix*mv;
      vUv = position.xy; vF = aM.x > .5 ? t : 1. - t; vK = aM.y;
    }

layers.fragment:
uniform vec3 uCR, uCB; varying vec2 vUv; varying float vF, vK;
    void main(){ float d = dot(vUv, vUv), g = exp(-d*28.), c = exp(-d*160.);
      vec3 col = mix(uCR, uCB, vK);
      gl_FragColor = vec4((col*g*1.4 + mix(col, vec3(1.), .6)*c*1.6)*(.3 + vF), 1.); }

layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){
      float u = uTime - aT - 0.18; if (u < 0. || u > 0.8){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 5.5; vP = position.xy*S; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float r = length(vP), R = 5.0, E = 0.35;
      float k = clamp(vU/E, 0., 1.), rr = R*k;                               // linear expansion
      float held = step(E, vU), pk = vU >= E && vU < E + .033 ? 1.7 : 1.;    // 2-frame peak when it reaches the limit
      float fade = 1. - smoothstep(E + .12, E + .45, vU);
      float w = mix(.03, .018, k);
      float ring = exp(-pow(abs(r - rr)/w, 2.4)), hot = lcore(r - rr, w*.3);
      float wake = smoothstep(rr - .7, rr, r)*step(r, rr)*(1. - held)*.03;  // faint thin wake just behind the moving front (ornament, dimmer than the limit)
      float lim = (.55 + .45*held)*pk*fade;
      float core = exp(-r*r*3.)*(vU < .033 ? 1.1 : .5*exp(-vU*9.));            // opening glow at the Fighter
      float edge = smoothstep(5.5, 5.2, r);
      vec3 outc = (uOrange*(ring*lim + wake*fade + core*.6) + mix(uGold, vec3(1.), .4)*hot*lim*.6)*edge;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

layers.vertex:
attribute vec3 aO; attribute float aT, aK, aS; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 0.5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5){
        float S = .75*aS; vP = position.xy/.75*.75; vP = position.xy*.75;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .035, -position.y*S), 1.);
      } else {
        vec3 f = cameraPosition - aO; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
        float Wd = .45*aS, H = 1.2*aS;
        vP = position.xy;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + rt*position.x*Wd + vec3(0., (position.y*.5 + .5)*2.*H + .1, 0.), 1.);
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec3 outc;
      if (vK < .5){
        float t = vU/0.5, r = length(vP);
        float R = mix(.12, .6, 1. - pow(1. - t, 3.)), f = pow(1. - t, 1.6);
        float ring = exp(-pow(abs(r - R)/.018, 2.4)), hot = lcore(r - R, .005);
        float flash = exp(-r*r*18.)*(vU < .033 ? 1. : 0.);
        outc = (uOrange*(ring*.9 + flash*.8) + mix(uGold, vec3(1.), .4)*hot*.6)*f*smoothstep(.75, .66, r);
      } else {
        // three thin streaks rising and thinning out; soft everywhere, zero at the quad edges
        float x = vP.x, y = vP.y*.5 + .5, t = vU/0.5;
        float lum = 0.;
        for (int i=0;i<3;i++){
          float fi = float(i), ox = (fi - 1.)*.42, dl = fi == 1. ? 0. : .05;
          float tt = clamp((vU - dl)/.3, 0., 1.);
          float head = tt*1.1, tail = head - .45;
          float seg = smoothstep(tail, tail + .25, y)*smoothstep(head + .02, head - .12, y);
          lum += exp(-pow((x - ox)/.05, 2.))*seg*(1. - smoothstep(.55, 1., t))*(fi == 1. ? 1. : .6);
        }
        outc = mix(uOrange, uGold, .5)*lum*.7*smoothstep(1., .8, abs(x))*smoothstep(1., .9, y);
      }
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

