layers.fragment:
uniform vec3 uOrange, uMoon; varying vec3 vN, vRock; varying float vHeat;
    void main(){ vec3 n = normalize(vN); float l = .12 + .6*max(dot(n, uMoon), 0.) + .15*max(n.y, 0.);
