      gl_FragColor = vec4((col*g + mix(col, vec3(1.), .6)*c) * (1. + 3.*vF*vF), 1.); }

constants.ARC:
vec3 arcAt(vec3 a, vec3 b, float f, float sd){
    vec3 d = b - a; float L = length(d); vec3 side = normalize(cross(d, vec3(0., 1., 0.)));
    float h = fract(sin(sd*91.7)*43758.5), sg = h < .5 ? -1. : 1.;
    float lat = sg*L*(.03 + .025*fract(h*7.))*sin(3.14159*f) + L*.008*sin(6.28318*f + h*6.);   // main bow + a faint S wobble
    float up = L*.015*sin(3.14159*f);
    return mix(a, b, f) + side*lat + vec3(0., up, 0.); }

layers.vertex:
attribute vec3 aO, aE; attribute float aT, aS; uniform float uTime; varying vec2 vP; varying float vU; vec3 arcAt(vec3 a, vec3 b, float f, float sd){
    vec3 d = b - a; float L = length(d); vec3 side = normalize(cross(d, vec3(0., 1., 0.)));
    float h = fract(sin(sd*91.7)*43758.5), sg = h < .5 ? -1. : 1.;
    float lat = sg*L*(.03 + .025*fract(h*7.))*sin(3.14159*f) + L*.008*sin(6.28318*f + h*6.);   // main bow + a faint S wobble
    float up = L*.015*sin(3.14159*f);
