      vec4 mv = viewMatrix*vec4(arcAt(aO, aE, min(u/tt, 1.), aT), 1.); mv.xyz += normalize(-mv.xyz)*.1;
      mv.xy += position.xy*aS*grow*1.25; vP = position.xy; vU = u; gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    void main(){                                              // opaque arcane sphere: lit body, thin bright rim, small highlight, short halo
