layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    void main(){                                              // astral star: 4 long points + 4 short, bright core, soft halo
      vec2 p = vP; float r = length(p), a = atan(p.y, p.x);
      float fl = .5 + .5*sin(a*7. + vU*40.)*sin(a*3. - vU*23.);             // flickering flame tongues
      float sphere = smoothstep(.34, .28, r), corona = exp(-pow(max(r - .3, 0.)/(.07 + .09*fl), 2.))*step(.28, r);
      float core = exp(-r*r*40.), halo = exp(-r*r*5.)*.2;
      vec3 o = (uOrange*(corona*1.1 + halo + sphere*.5) + uGold*sphere*.9 + vec3(1., .9, .7)*core*.9)*smoothstep(1., .85, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying float vS, vY, vF; vec3 arcAt(vec3 a, vec3 b, float f){ return mix(a, b, f); }
    void main(){
      float u = uTime - aT - 0.1, L = length(aE - aO), tt = L/18;
      if (u < 0. || u > tt + .2){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = (aE - aO)/L;
      float head = min(u*18, L), tail = max(0., head - .7) + max(0., u - tt)/.2*1.7;   // after the hit, the tail catches up
      if (head - tail < .01){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = position.x*.5 + .5;
      float fa = mix(tail, head, s)/L;
      vec3 P = arcAt(aO, aE, fa), T = normalize(arcAt(aO, aE, min(fa + .01, 1.)) - arcAt(aO, aE, max(fa - .01, 0.)));
      vec3 side = normalize(cross(T, P - cameraPosition));
      vS = s; vY = position.y; vF = 1. - clamp((u - tt)/.2, 0., 1.);
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*(.02 + .09*s), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vF;
    void main(){ float a = pow(vS, 1.6)*exp(-vY*vY*5.), c = pow(vS, 3.)*exp(-vY*vY*30.);
      vec3 o = (mix(uOrange, uGold, .6)*a*.55 + vec3(1., .95, .85)*c*.35)*vF;
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT, life = aK < .5 ? .2 : (aK < 1.5 ? .55 : .28);
      if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5 || aK > 1.5){
        vec4 mv = viewMatrix*vec4(aO,1.); mv.xyz += normalize(-mv.xyz)*.3;
        float S = aK < .5 ? .4 : .5; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv;
      } else {
        float S = .62; vP = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p-a, ba = b-a; float h = clamp(dot(pa,ba)/dot(ba,ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      vec2 p = vP; float lum = 0., hot = 0.;
      if (vK > 1.5){
        // rear flash (Interrupt): an asymmetric burst of rays from the stab point — long up-and-forward, short elsewhere
        float r = length(p), a = atan(p.y, p.x), t = vU/.28, f = pow(1. - t, 1.6)*(vU < .033 ? 1.7 : 1.);
        float N = 9., fa = floor(a/6.2832*N + .5), ac = fa/N*6.2832;
        float h = fract(sin(fa*37.1)*4375.5);
        float L = (.1 + .3*pow(max(0., cos(ac - .75)), 2.) + .06*h)*(1. - pow(1. - clamp(vU/.07, 0., 1.), 3.));
        float d = abs(sin(a - ac))*r, w = .014*(1. - r/max(L, .01)) + .003;
        float ray = exp(-pow(d/w, 2.))*smoothstep(L, L*.55, r)*smoothstep(.02, .06, r);
        lum += ray*f*1.2 + exp(-r*r*60.)*f*1.4; hot += ray*f*.5 + exp(-r*r*200.)*f;
        lum *= smoothstep(.5, .42, r); hot *= smoothstep(.5, .42, r);
      } else if (vK < .5){
        // splash: a soft burst + droplets thrown out radially, irregular lengths, thinning as they fly
        float t = vU/.2, f = pow(1. - t, 1.4), r = length(p), a = atan(p.y, p.x);
        float k = 1. - pow(1. - clamp(t/.6, 0., 1.), 3.);
        lum += exp(-r*r*(90. + 400.*t))*f*1.3;                               // splat core
        for (int j=0;j<9;j++){
          float fj = float(j), h = fract(sin(fj*71.3)*4375.5), aj = fj*.698 + h*.5;
          vec2 dir = vec2(cos(aj), sin(aj)); float Rj = (.12 + .2*h)*k;       // each droplet travels its own distance
          vec2 q = p - dir*Rj; float sz = (.018 + .014*fract(h*7.))*(1. - .6*t);
          float along = dot(q, dir), across = dot(q, vec2(-dir.y, dir.x));
          lum += exp(-(across*across)/(sz*sz) - (along*along)/(sz*sz*4.))*f;  // stretched along its motion
        }
        hot = lum*.5;
        lum *= smoothstep(.4, .32, r); hot *= smoothstep(.4, .32, r);
      } else {
        // Slow: a thin ring settles inward (weight), three small chevrons point to the centre, then it fades
        float t = vU/.55, f = pow(1. - smoothstep(.45, 1., t), 1.5)*smoothstep(0., .08, t);
        float R = mix(.5, .38, 1. - pow(1. - clamp(t/.3, 0., 1.), 3.)), r = length(p);
        float ring = exp(-pow((r - R)/.009, 2.));
        float ch = 0.;
        for (int i=0;i<3;i++){
          float a = float(i)*2.0944 + .5; vec2 u = vec2(cos(a), sin(a)), n = vec2(-u.y, u.x);
          vec2 q = vec2(dot(p, n), dot(p, u)) - vec2(0., R - .09);   // chevron just inside the ring, tip pointing inward
          float dv = min(seg(q, vec2(0., -.035), vec2(-.045, .025)), seg(q, vec2(0., -.035), vec2(.045, .025)));
          ch += exp(-pow(dv/.007, 2.));
        }
        lum += (ring*.9 + ch*.8)*f; hot += ring*f*.3;
      }
      vec3 outc = mix(uOrange, uGold, .6)*lum + mix(uGold, vec3(1., .96, .88), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

layers.vertex:
attribute vec3 aO, aV; attribute vec2 aT; uniform float uTime, uW; uniform vec2 uRes; varying float vF; varying vec2 vQ;
    vec3 sim(float t){ float k = 5., e = exp(-k*t); vec3 p = aO + aV*(1.-e)/k; p.y += 4.*((1.-e)/(k*k) - t/k); return p; }
    void main(){
      float age = uTime - aT.x; if (age < 0. || age > aT.y){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 ch = projectionMatrix*viewMatrix*vec4(sim(age),1.), ct = projectionMatrix*viewMatrix*vec4(sim(max(age-.03,0.)),1.);
      vec2 d = (ch.xy/ch.w - ct.xy/ct.w)*uRes; float L = length(d); vec2 dir = L > .5 ? d/L : vec2(1.,0.), nrm = vec2(-dir.y, dir.x);
      float s = position.y + .5; vec4 c = mix(ct, ch, s);
      c.xy += (nrm*position.x*uW*2. + dir*(s-.5)*uW)*2./uRes*c.w;
      gl_Position = c; vF = 1. - age/aT.y; vQ = vec2(position.x*2., s);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vF; varying vec2 vQ;
    void main(){ float a = exp(-vQ.x*vQ.x*3.)*vQ.y, c = exp(-vQ.x*vQ.x*14.)*vQ.y;
      gl_FragColor = vec4((mix(uOrange, uGold, vF)*a*1.3 + vec3(1., .95, .85)*c*vF)*(.4 + 1.3*vF*vF), 1.); }

layers.vertex:
attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.0){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK > 3.5){                                          /* Combust II: a low crown of flames around the target (the torso stays clear), upright, only turned about Y */
        vec3 fw = cameraPosition - aO; fw.y = 0.; fw = normalize(fw); vec3 rt = vec3(fw.z, 0., -fw.x);
        float H = 1.45*(1. + .06*aD.x), W = .8*(1. + .06*aD.x);
        vP = vec2(position.x*W, (position.y*.5 + .5)*H);
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + fw*.12 + rt*vP.x + vec3(0., vP.y, 0.), 1.); return; }
      if (aK > 2.5){                                          // Weave: a resource mote flies back to the caster on a curved path
        float k = clamp((u - aD.w)/.45, 0., 1.); if (u < aD.w || k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float e = k*k*(3. - 2.*k); vec3 A = aO + vec3(0., 1.2, 0.), B = aD.xyz;
        vec3 side = normalize(cross(B - A, vec3(0., 1., 0.)))*sin(aD.w*37.)*.8;
        vec3 P = mix(A, B, e) + (side + vec3(0., .9, 0.))*sin(3.14159*e);
        vec4 mv = viewMatrix*vec4(P, 1.); float S = .09; mv.xy += position.xy*S; vU = k; gl_Position = projectionMatrix*mv; return; }
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.32; mv.xy += position.xy*vec2(.26, .3); gl_Position = projectionMatrix*mv; }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.75;   /* well in front of the chest: the body never cuts the quad */ float S = .8*(1. + .15*aD.x); mv.xy += position.xy*S; vP = position.xy*.8; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0., t = vU/1.0;
      if (vK < .5){
        float r = length(vP), e = pow(clamp(vU/.25, 0., 1.), 3.), R = .8 - .65*e, f = (vU < .033 ? 1.5 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += exp(-pow(abs(r - R)/.016, 2.4))*f; hot += lcore(r - R, .005)*f*.6;
        lum *= smoothstep(.95, .85, r); hot *= smoothstep(.95, .85, r);
      } else if (vK < 1.5){
        // Manifest · Burn mark: a small flame sigil held on the target after the impact (brief, then the status cue takes over)
        float x = vP.x, y = vP.y*.5 + .5, t = clamp((vU - .2)/.6, 0., 1.);
        vec2 q = vec2(x*2.2, (y - .55)*4.6); float r = length(q);
        float flame = smoothstep(.55, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2)))*smoothstep(-.9, -.4, q.y)*(1. - smoothstep(.55, 1.1, q.y + .1*sin(vU*30.)));
        float edge = flame*(1. - smoothstep(.3, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2))));
        float f = step(.2, vU)*(vU < .233 ? 1.8 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += (flame - edge*.7)*f*1.1; hot = edge*f*.2;
        lum *= smoothstep(1., .75, abs(x)); hot *= smoothstep(1., .75, abs(x));
      } else {
        if (vK > 3.5){                                        /* flame crown: tongues erupt around the body and lean outward, tallest at the
                                                                 flanks, low in the middle so the silhouette stays readable; die from the base up */
          float x = vP.x, y = vP.y, u = vU, ax = abs(x);
          #define H2(q) fract(sin(dot(q, vec2(127.1, 311.7)))*43758.5)
          float rise = 1. - pow(1. - clamp(u/.22, 0., 1.), 3.);
          float side = smoothstep(.14, .36, ax)*smoothstep(.8, .52, ax);            /* flanks of the body */
          float Hx = mix(.28, 1.1, side)*rise;                                        /* low in front of the torso, tall at the sides */
          float xs = x - sign(x)*.22*pow(clamp(y/1.3, 0., 1.), 1.5);                 /* tongues lean outward, away from the body */
          vec2 pn = vec2(xs*6.5, y*1.9 - u*6.); vec2 ip = floor(pn), fp = fract(pn); fp = fp*fp*(3. - 2.*fp);
          float n = mix(mix(H2(ip), H2(ip + vec2(1., 0.)), fp.x), mix(H2(ip + vec2(0., 1.)), H2(ip + vec2(1., 1.)), fp.x), fp.y);
          vec2 pm = vec2(xs*12., y*3.6 - u*9.); ip = floor(pm); fp = fract(pm); fp = fp*fp*(3. - 2.*fp);
          float n2 = mix(mix(H2(ip), H2(ip + vec2(1., 0.)), fp.x), mix(H2(ip + vec2(0., 1.)), H2(ip + vec2(1., 1.)), fp.x), fp.y);
          float h = Hx*(.75 + .5*n);
          float yy = clamp(y/max(h, .01), 0., 1.);
          float dens = smoothstep(1., .55, yy)*step(y, h)*smoothstep(0., .22, y)*smoothstep(.8, .55, abs(xs));
          dens *= smoothstep(.2, .72, n*.55 + n2*.45 + .4*(1. - yy));
          float die = clamp((u - .5)/.35, 0., 1.); dens *= smoothstep(die*1.5 - .1, die*1.5 + .3, y)*(1. - die*die);   /* dies from the base up */
          float T = clamp((1. - yy*1.1)*(.7 + .45*n2)*mix(.8, 1., side), 0., 1.);
          vec3 smoke = vec3(.03, .02, .015), red = vec3(.45, .05, .01), org = vec3(.95, .33, .04), yel = vec3(1., .75, .35);
          vec3 col = T < .3 ? mix(smoke, red, T/.3) : (T < .7 ? mix(red, org, (T - .3)/.4) : mix(org, yel, (T - .7)/.3));
          vec3 c = col*dens*(.12 + .85*T*T); float al = dens*(1. - T)*(1. - T)*.1;
          if (!(max(c.r, max(c.g, max(c.b, al))) >= .002)) discard; gl_FragColor = vec4(c, al); return; }
        if (vK > 2.5){ float r = length(vP); float m = exp(-r*r*8.)*(1. - vU)*1.6;       // Weave mote
          vec3 o = uGold*m + vec3(1., .95, .8)*exp(-r*r*40.)*(1. - vU);
          if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 0.); return; }
        /* Combust (icon), physical fire: a hot core swells inside the chest, then bursts into flame tongues that cool
           from yellow to red to smoke as they travel out (premultiplied: hot adds light, smoke darkens) - no ring, no mark */
        float r = length(vP), a = atan(vP.y, vP.x), b = vU - 0.3;
        float h1 = fract(sin(dot(floor(vP*9.), vec2(127.1, 311.7)))*43758.5);
        vec2 pn = vP*6. - vP/max(r, .05)*max(b, 0.)*5. + vec2(3.7, 1.3);   /* cartesian noise pushed outward: no pole at the centre */
        vec2 ip = floor(pn), fp = fract(pn); fp = fp*fp*(3. - 2.*fp);
        #define HH(q) fract(sin(dot(q, vec2(127.1, 311.7)))*43758.5)
        float n = mix(mix(HH(ip), HH(ip + vec2(1., 0.)), fp.x), mix(HH(ip + vec2(0., 1.)), HH(ip + vec2(1., 1.)), fp.x), fp.y);
        float dens = 0., T = 0.;
        if (b < 0.){ float k = vU/0.3;                                     /* build-up: a small core glows through */
          dens = exp(-r*r*(90. - 60.*k*k))*(.4 + .6*k); T = .55 + .45*k;
        } else if (b < .6){ float kk = smoothstep(.25, .6, b); float fl = .85 + .15*sin(vU*47.)*sin(vU*29.); dens = exp(-r*r*30.)*(1. - kk)*fl; T = .9 - .3*kk;   /* II: the core keeps burning inside the pillar until the flame dies */
        } else if (b < 0.){
          float t = clamp(b/.6, 0., 1.), e = 1. - pow(1. - clamp(b/.15, 0., 1.), 3.);
          float rays = 0.;
          for (int i = 0; i < 14; i++){ float fi = float(i), hh = fract(sin(fi*71.3)*4375.5);
            float ac = fi*.4488 + (hh - .5)*.35, r0 = .12 + .08*fract(hh*7.3), L = (.28 + .3*hh)*e;   /* each tongue starts at its own radius, not all at the centre */                      /* 14 short tongues of irregular length */
            float aw = a - ac + .9*(r - .2)*(hh - .5);   /* tongues bend a little: gaps never point at the centre */
            float d = sin(aw)*r, along = cos(aw)*r - r0;
            float w = (.03 + .07*(1. - along/max(L, .01)))*step(0., along);
            rays += exp(-pow((d - .04*sin(along*12. - b*20. + fi)*along)/w, 2.))*smoothstep(L, L*.3, along)*smoothstep(0., .1, along); }
          rays *= smoothstep(.1, .26, r);                                                 /* no pinch point where the tongues would meet */
          dens = (min(rays, 1.)*(.55 + .6*n) + exp(-r*r*14.)*(.55 + .7*n)*(1. - t*.8))*(1. - t*t);   /* a soft, noisy fire ball fills the middle */
          T = clamp((1. - r/.6)*(1. - t*.9)*(.7 + .5*n), 0., 1.);                          /* hottest at the centre, cools outward and over time */
        }
        dens *= smoothstep(.75, .55, r);
        vec3 smoke = vec3(.03, .02, .015), red = vec3(.45, .05, .01), org = vec3(.95, .33, .04), yel = vec3(1., .75, .35);
        vec3 col = T < .3 ? mix(smoke, red, T/.3) : (T < .7 ? mix(red, org, (T - .3)/.4) : mix(org, yel, (T - .7)/.3));
        vec3 c = col*dens*(.15 + 1.1*T*T);
        float al = dens*(1. - T)*(1. - T)*.18;   /* only a faint smoke veil: a strong one darkens the fog around the target and reveals its silhouette */
        if (!(max(c.r, max(c.g, max(c.b, al))) >= .002)) discard; gl_FragColor = vec4(c, al); return;
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 0.);
    }

layers.vertex:
attribute vec3 aO; attribute vec2 aT, aI; uniform float uTime; varying vec2 vP; varying float vA, vHot;
    void main(){
      float u = uTime - aT.x, h = uTime - aT.y; if (u < 0. || h > .12){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float th = aI.x*6.2832/aI.y + uTime*2.4, R = .5*(h > 0. ? 1. - h/.12*(h/.12) : 1.);   /* orbit; at the hit they are pulled in, accelerating */
      vec3 P = aO + vec3(cos(th)*R, .08*sin(uTime*5. + aI.x*2.), sin(th)*R);
      vA = smoothstep(0., .2, u); vHot = h > 0. ? 1. + 1.5*h/.12 : 1.;
      vec4 mv = viewMatrix*vec4(P, 1.); mv.xyz += normalize(-mv.xyz)*.1; float S = .16; mv.xy += position.xy*S*vec2(1., 1.4); vP = position.xy;
      gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform float uTime; uniform vec3 uGold, uOrange; varying vec2 vP; varying float vA, vHot;
    void main(){                                      /* a small flame: teardrop, flickering tip, hot core */
      vec2 q = vP; float fl = .9 + .1*sin(uTime*30. + q.y*6.);
      float d = length(vec2(q.x*(1.5 + .9*max(q.y, 0.)), q.y + .25));
      float body = smoothstep(.75*fl, .2, d), core = exp(-(q.x*q.x*30. + pow(q.y + .35, 2.)*20.));
      float m = vA*smoothstep(1., .85, length(q)); vec3 o = (vec3(.6, .1, .02)*body*.7 + vec3(1., .5, .1)*core*.8*vHot)*m;   /* small physical flame: red body, orange core, a bit of smoke */
      float al = body*(1. - core)*.35*m;
      if (max(o.r, max(o.g, max(o.b, al))) < .002) discard; gl_FragColor = vec4(o, al); }

layers.vertex:
attribute vec3 aO; attribute float aYaw; attribute vec4 aS; uniform float uTime; varying vec2 vF; varying float vAge, vFrom, vTo;
    void main(){
      if (aS.w < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float age = uTime - aS.z, S = age < .24 ? 1.45 : .98;
      vec2 l = position.xz*S;                           // local metres, -z = forward
      float c = cos(aYaw), s = sin(aYaw);
      vec2 w = vec2(c*l.x + s*l.y, -s*l.x + c*l.y);
      vF = vec2(l.x, -l.y); vAge = age; vFrom = aS.x; vTo = aS.y;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(w.x*.75, .95, w.y*.75), 1.);   // entry pulse on the waist orbit plane, not the ground
    }

layers.fragment:
uniform float uTime; uniform vec3 uCW, uCT; varying vec2 vF; varying float vAge, vFrom, vTo; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float lineCore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec2 p = vF; float r = length(p); vec3 col = uCW;
      float rr = mix(.4, 1.35, eox(clamp(vAge/.2, 0., 1.))), fade = 1. - clamp(vAge/.24, 0., 1.);
      float pulse = (lineCore(r - rr, .012)*1.3 + exp(-pow((r-rr)/.09, 2.))*.35)*fade*fade*step(0., vAge);
      float disk = exp(-r*r*6.)*(vAge < .033 ? 1.2 : 0.);
      vec3 outc = col*(pulse + disk) + mix(col, vec3(1.), .55)*pulse*.25;   // entry only: no persistent ground seal in Weave
      float S = vAge < .24 ? 1.45 : .98;
      outc *= smoothstep(S, S*.78, r);
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc*1.1, 1.);
    }

layers.vertex:
attribute vec3 aO, aV; attribute vec2 aT; attribute float aC; uniform float uTime; varying vec2 vUv; varying float vF; varying float vC;
    void main(){
