    void main(){ float u = uTime - aT; if (u < 0. || u > 1.05){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK > 4.5){                                          // cone frost front: ground quad centred on the caster, +y = forward
        vec3 fw = vec3(aD.x, 0., aD.y), rt = vec3(-aD.y, 0., aD.x); float S = aD.z + .4;
        vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + rt*vP.x + fw*vP.y + vec3(0., .03, 0.), 1.); return; }
      if (aK > 2.5){                                          // Weave: a resource mote flies back to the caster on a curved path
        float k = clamp((u - aD.w)/.45, 0., 1.); if (u < aD.w || k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float e = k*k*(3. - 2.*k); vec3 A = aO + vec3(0., 1.2, 0.), B = aD.xyz;
        vec3 side = normalize(cross(B - A, vec3(0., 1., 0.)))*sin(aD.w*37.)*.8;
        vec3 P = mix(A, B, e) + (side + vec3(0., .9, 0.))*sin(3.14159*e);
        vec4 mv = viewMatrix*vec4(P, 1.); float S = .09; mv.xy += position.xy*S; vU = k; gl_Position = projectionMatrix*mv; return; }
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.32; mv.xy += position.xy*vec2(.26, .3); gl_Position = projectionMatrix*mv; }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.2, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3; float S = .75; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0., t = vU/1.05;
      if (vK > 4.5){
        // frost front inside the cone (6 m, 80°): a thin bright front sweeps out, a faint rime stays behind, cone edges as thin lines
        float Rm = 6., hf = .698, r = length(vP), a = atan(vP.x, vP.y);
        float inside = smoothstep(hf + .03, hf - .03, abs(a))*smoothstep(Rm + .15, Rm - .1, r)*step(0., vP.y);
        float F = mix(.4, Rm, 1. - pow(1. - clamp(vU/.35, 0., 1.), 2.)), fade = 1. - smoothstep(.75, 1., vU);
        float front = exp(-pow((r - F)/.1, 2.))*(1. - smoothstep(.3, .45, vU)*.7);
        float rime = smoothstep(F, F - 1.5, r)*.05;
        float edge = exp(-pow((abs(a) - hf)*r/.018, 2.))*step(r, F)*step(.3, r)*.5;
        lum = (front*.9 + rime + edge)*inside*fade; hot = front*inside*fade*.35;
        lum *= smoothstep(.2, .6, r);
      } else if (vK < .5){
        float r = length(vP), e = pow(clamp(vU/.25, 0., 1.), 3.), R = .8 - .65*e, f = (vU < .033 ? 1.5 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += exp(-pow(abs(r - R)/.016, 2.4))*f; hot += lcore(r - R, .005)*f*.6;
        lum *= smoothstep(.95, .85, r); hot *= smoothstep(.95, .85, r);
      } else if (vK < 1.5){
        // Manifest · Burn mark: a small flame sigil held on the target after the impact (brief, then the status cue takes over)
        float x = vP.x, y = vP.y*.5 + .5, t = clamp((vU - .2)/.6, 0., 1.);
        vec2 q = vec2(x*2.2, (y - .55)*4.6); float r = length(q);
        float flame = smoothstep(.55, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2)))*smoothstep(-.9, -.4, q.y)*(1. - smoothstep(.55, 1.1, q.y + .1*sin(vU*30.)));
        float edge = flame*(1. - smoothstep(.3, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2))));
        float f = step(.2, vU)*(vU < .233 ? 1.8 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += (flame - edge*.7)*f*1.1; hot = edge*f*.2;
        lum *= smoothstep(1., .75, abs(x)); hot *= smoothstep(1., .75, abs(x));
      } else {
        if (vK > 2.5){ float r = length(vP); float m = exp(-r*r*8.)*(1. - vU)*1.6;       // Weave mote
          vec3 o = uGold*m + vec3(1., .95, .8)*exp(-r*r*40.)*(1. - vU);
          if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); return; }
        // compact fire burst on the target: bright sphere pops, flame tongues flare out short and die fast
        float r = length(vP), a = atan(vP.y, vP.x), t2 = clamp(vU/.35, 0., 1.);
        float R = .12 + .25*(1. - pow(1. - t2, 3.)), fl = .5 + .5*sin(a*9. + 2.)*sin(a*4. - 1.);
        float body = exp(-r*r*(30. + 50.*t2))*(vU < .033 ? 2. : 1.4*(1. - t2));
        float tongues = pow(max(0., cos(a*6.))*fl, 2.)*smoothstep(R + .18*fl, R, r)*smoothstep(.05, .15, r)*(1. - t2);
        float rim = exp(-pow((r - R)/.03, 2.))*(1. - t2)*.8;
        lum += body*.6; hot = body*.3;                                     /* short cold flash */
        for (int i = 0; i < 7; i++){ float fi = float(i), hh = fract(sin(fi*37.7)*4375.5);
          float an = 3.14159 + (fi/6. - .5)*2.6 + (hh - .5)*.3;                 /* shards fly back and to the sides */
          vec2 dir = vec2(cos(an), sin(an) + .25), nr = vec2(-dir.y, dir.x);
          vec2 c = dir*(.06 + .45*(1. - pow(1. - t2, 2.)))*(.7 + .5*hh) + vec2(0., -.25*t2*t2);
          vec2 q = vP - c; float al = dot(q, normalize(dir)), ac = dot(q, normalize(nr));
          float sz = .035 + .025*hh; float sh = exp(-(abs(al)/(sz*1.8) + abs(ac)/(sz*.6))*2.5);
          lum += sh*(1. - t2)*1.2; hot += sh*(1. - t2)*.5; }
        lum *= smoothstep(.75, .62, r); hot *= smoothstep(.75, .62, r);
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }

constants.ICE_GLSL:
uniform sampler2D uBG; uniform vec2 uRes;
float ih(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453); }
float ivn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
  return mix(mix(ih(i), ih(i + vec2(1., 0.)), f.x), mix(ih(i + vec2(0., 1.)), ih(i + vec2(1., 1.)), f.x), f.y); }
float ivn3(vec3 p){ return mix(ivn(p.xy + floor(p.z)*17.13), ivn(p.xy + (floor(p.z) + 1.)*17.13), smoothstep(0., 1., fract(p.z))); }
/* n: facet normal (world, facing the camera) · V: to camera · B: unused · h: 0 base → 1 point · q: coords on the crystal
   (x across, y along) · L: key light. Opaque output: the background comes in through the refraction. */
vec4 iceShade(vec3 n, vec3 V, vec3 B, float h, vec2 q, vec3 L){
  n = dot(n, V) < 0. ? -n : n;                                             /* face the camera whatever the winding */
  vec3 j = vec3(ih(n.xy*13.1 + q.x*.01), ih(n.yz*7.3 + 1.7), ih(n.zx*5.7 + 3.1)) - .5;
  vec3 fn = normalize(n + j*.3);                                           /* each facet tilted a little: reflections change facet to facet */
  float nv = clamp(dot(fn, V), 0., 1.), fr = .04 + .96*pow(1. - nv, 5.);
  vec3 vn = (viewMatrix*vec4(fn, 0.)).xyz;
  vec2 suv = gl_FragCoord.xy/uRes, off = vn.xy*(.05 + .07*(1. - nv));      /* refraction: the scene behind, bent by the facet */
  vec3 bg = vec3(texture2D(uBG, suv - off*1.04).r, texture2D(uBG, suv - off).g, texture2D(uBG, suv - off*.96).b);
  float thick = clamp(.3 + .7*nv, 0., 1.)*(1. - .55*h);                    /* thick body, thin clear point */
  vec3 absorb = mix(vec3(.7, .9, 1.), vec3(.08, .32, .8), thick);
  vec3 p3 = vec3(q*vec2(3.5, 1.4), h*2.3);
  float cloud = ivn3(p3*1.3)*.6 + ivn3(p3*3.1)*.4;
  float frost = smoothstep(.55, .85, cloud);                               /* cloudy white frost inside */
  float fid = ih(floor(n.xz*37.) + floor(n.y*29.));                        /* one random value per facet */
  float cr = pow(1. - abs(fract(dot(q, vec2(2.3, .7))*1.7 + fid*3.) - .5)*2., 60.)*step(.72, fid);   /* a straight inner crack on some facets */
  vec3 inner = bg*absorb*1.2 + vec3(.03, .16, .42)*thick + vec3(.6, .78, .92)*(frost*.28*thick + cr*.35);
  inner *= .75 + .5*fid;                                                   /* facets transmit differently: they read as separate planes */
  vec3 R = reflect(-V, fn);
  vec3 sky = mix(vec3(.03, .07, .16), vec3(.2, .42, .78), smoothstep(-.3, .9, R.y))
           + vec3(.45, .7, .95)*pow(max(dot(R, normalize(vec3(-.5, .6, .6))), 0.), 6.)*.35;   /* a broad bright window in the reflection */
  float sL = max(dot(R, L), 0.), sC = max(dot(R, normalize(V + vec3(0., .6, 0.))), 0.);
  vec3 col = mix(inner, sky, clamp(fr*.7 + .25*pow(fid, 5.), 0., .75)) + vec3(.95, .98, 1.)*(pow(sL, 220.)*5. + pow(sC, 160.)*1.6 + pow(sL, 18.)*.25);
  col += vec3(.6, .85, 1.)*smoothstep(.9, 1., h)*.2;                      /* a cold glint at the very point */
  return vec4(col, 1.);
}

layers.vertex:
attribute vec3 aO; attribute vec4 aS, aD; attribute float aT; attribute vec3 bary; uniform float uTime; varying vec3 vN, vV, vB; varying vec2 vQ; varying float vH;
    void main(){
      float u = uTime - aT - aD.x, life = aD.w > .5 ? .4 : 1.05; if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = clamp(u/(aD.w > .5 ? .06 : .12), 0., 1.), rise = 1. - pow(1. - k, 3.), sink = aD.w > .5 ? smoothstep(.25, .4, u) : smoothstep(.72, 1.05, u);   // II clamps: snap shut, brief
      vec3 sc = vec3(aS.x, aS.y, aS.x);
      vec3 p = position*sc, n = normalize(normal/sc);
      float cy = cos(aS.z), sy = sin(aS.z); p = vec3(cy*p.x - sy*p.z, p.y, sy*p.x + cy*p.z); n = vec3(cy*n.x - sy*n.z, n.y, sy*n.x + cy*n.z);
      float ct = cos(aS.w), st = sin(aS.w); vec3 ax = vec3(cos(aD.y), 0., sin(aD.y));   // lean about a horizontal axis
      p = p*ct + cross(ax, p)*st + ax*dot(ax, p)*(1. - ct); n = n*ct + cross(ax, n)*st + ax*dot(ax, n)*(1. - ct);
      vec3 W = aO + p - vec3(0., ((1. - rise) + sink)*aS.y*1.05, 0.);                 // erupts out of the ground, sinks back into it
      vN = n; vV = normalize(cameraPosition - W); vB = bary; vH = position.y; vQ = vec2((position.x - position.z)*aS.x + aD.z*9., position.y*aS.y);
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.);
    }

