uniform float uTime; uniform vec3 uV, uL, uD; varying vec2 vP; varying float vU, vK, vLen; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float line(float d, float w){ return exp(-d*d/(w*w)); }
    void main(){ vec3 c = vec3(0.); float al = 0.;
      if (vK < .5){
        float r = length(vP), a = atan(vP.y, vP.x), R = 3.5;
        float fin = eox(clamp((vU - .3)/1.6, 0., 1.)), fout = 1. - smoothstep(4.0, 4.5, vU);
        float Rr = R*mix(.4, 1., fin), f = fin*fout;
        float rim = line(r - Rr, .03)*.22 + exp(-pow((r - Rr)/.25, 2.))*.04;              /* faint outer border */
        float sw = a + 2.2*log(max(r, .05)) - vU*.35;                                     /* 4 wide spiral arms turning inward, slowly */
        float arm = pow(.5 + .5*cos(4.*sw), 5.)*smoothstep(Rr, Rr*.6, r)*smoothstep(.55, 1.1, r);
        float streak = .6 + .4*sin(sw*4. + r*6. - vU*3.);
        float hz = line(r - .62, .06)*1.2;                                                 /* violet event horizon */
        float core = smoothstep(.62, .45, r);                                              /* the black centre stays visible */
        c = (uV*rim + uL*line(r - Rr, .01)*.08)*f;                                        /* only the faint outer border stays on the ground */
        al = 0.;
        c *= smoothstep(R + .3, R + .1, r); al *= smoothstep(R + .3, R + .1, r);
      } else if (vK > 1.5){
        /* the orb in the air: a black sphere with a bright violet photon rim, a thin tilted accretion ring swirling
           around it and a soft glow - premultiplied so the core really reads black */
        vec2 q = vP; float r = length(q), a = atan(q.y, q.x);
        float core = 1. - smoothstep(.35, .37, r), rimL = line(r - .365, .015)*.9 + exp(-pow((r - .365)/.055, 2.))*.09;
        vec2 e = vec2(q.x, q.y*3.2); float er = length(e), ea = atan(e.y, e.x);
        float disk = line(er - .62, .035)*(.55 + .35*sin(ea*3. - uTime*2.5))*(1. - core*step(0., q.y));   /* ring passes behind the top */
        float swirl = pow(.5 + .5*cos(a*2. + r*9. - uTime*3.), 4.)*smoothstep(.95, .4, r)*smoothstep(.34, .5, r)*.35;
        c = uV*(rimL + disk*.62 + swirl*.35 + exp(-r*r*8.)*.018) + uL*(line(r - .365, .005)*.35 + disk*.12);
        al = core; c *= 1. - core;
        c *= smoothstep(1., .9, r); al *= smoothstep(1., .9, r);
      } else {
        /* the single convergence line (query): a bright arrow travels from the enemy to the centre over 0.6 s, then fades */
        float s = vP.x, y = vP.y, t = clamp(vU/0.6, 0., 1.), h = eox(t)*1.02;
        float body = line(y, .25)*smoothstep(h - .45, h, s)*step(s, h)*(1. - smoothstep(.75, 1., t));
        float head = line(y, .5)*line((s - h)*vLen, .12)*(1. - t*.6);
        c = (uV*body*1.6 + uL*(head*1.8 + body*.5))*smoothstep(0., .05, s); al = 0.;
      }
      if (!(max(c.r, max(c.g, max(c.b, al))) >= .002)) discard; gl_FragColor = vec4(c, al); }

layers.vertex:
attribute vec3 aO; attribute float aT; attribute vec2 aP; uniform float uTime; varying vec2 vS; varying float vU, vF, vD;
    vec3 armAt(float s, vec3 C, vec3 e1, vec3 e2, vec3 n, float spin, float grow){
      float r = mix(.36, 3.5, s*grow), a = aP.x*6.28318 + spin/6. - 2.8*r/3.5;
      a += sin(s*5. - uTime*.4 + aP.y*6.28318)*.16*sin(3.14159*s);          /* from the orb out to the outer border */
      vec3 G = vec3(C.x, .06, C.z);
      return G + (e1*cos(a) + e2*sin(a))*r + n*(C.y - .06)*pow(1. - s*grow, 2.2);      /* the arm EXTENDS out of the orb (scaling a spiral would read as a backwards spin) */      /* funnel: high at the orb, down to the ground at the rim */
    }
    void main(){
      float u = uTime - aT; if (u < 0. || u > 4.5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 C = aO + vec3(0., 1.35 + .05*sin(uTime*1.3), 0.);
      vec3 n = vec3(0., 1., 0.), d0 = vec3(0., 0., 1.);
      vec3 e1 = normalize(cross(n, d0)), e2 = cross(e1, n);
      float grow = 1. - pow(1. - clamp((u - .3)/1.6, 0., 1.), 3.), spin = -u*7.;            /* slower than the Vortex, swirling inward */
      float s = position.x + .5;
      vec3 P = armAt(s, C, e1, e2, n, spin, grow), T = normalize(armAt(min(s + .02, 1.), C, e1, e2, n, spin, grow) - armAt(max(s - .02, 0.), C, e1, e2, n, spin, grow));
      vec3 side = normalize(cross(n, T));
      float w = (.06 + .19*pow(s, .8) + .16*exp(-s*9.))*grow*(.74 + .26*sin(s*8. - u*.7 + aP.y*6.));                               /* wide at the orb: the violet rim leaks out into the arm */
      vec3 W = P + side*position.y*2.*w; vD = length(W - C);                             /* distance to the orb centre: round (never polygonal) base */
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.);
      vS = vec2(s, position.y*2.); vU = u + aP.y*7.; vF = smoothstep(.3, 1.9, u)*(1. - smoothstep(3.0, 4.5, u));   /* arms start invisible, reach full opacity mid-life, fade out slowly at the end */
    }

layers.fragment:
varying vec2 vS; varying float vU, vF, vD;
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      float s = vS.x, y = vS.y, t = vU;
      float n1 = vn(vec2(s*3.5 + t*1.4, y*2. + t*.4)), n2 = vn(vec2(s*5. + t*2., y*2.5 - t*.6));   /* texture flows INWARD */
      float n = n1*.65 + n2*.35, yy = y + (n1 - .5)*.5;
      float body = exp(-yy*yy*(2.2 + 1.5*step(0., yy)));
      float lick = smoothstep(.05, .95, n + .5*(1. - abs(yy)));
      float streak = smoothstep(.05, .95, vn(vec2(s*2. + t*1.1, yy*3.5 + n1*1.2))*.7 + vn(vec2(s*3.5 + t*1.4, yy*6.))*.3);
      float dens = body*lick*(.55 + .45*streak)*smoothstep(1., .93, s)*smoothstep(.0, .025, s)*smoothstep(1., .82, abs(y));
      float T = clamp((1. - .3*s)*(.4 + .6*body*mix(1., streak, .4))*(.9 + .2*n), 0., 1.);
      /* violet ramp: dark dust -> deep violet -> violet -> pale lilac only in the hottest veins */
      vec3 dust = vec3(.01, .006, .016), deep = vec3(.16, .03, .34), vio = vec3(.5, .2, 1.), lil = vec3(.63, .34, 1.);
      vec3 col = T < .25 ? mix(dust, deep, T/.25) : T < .6 ? mix(deep, vio, (T - .25)/.35) : mix(vio, lil, clamp((T - .6)/.4, 0., 1.));
      float emit = T < .25 ? .06 : .52*T, alpha = dens*mix(.35, .08, clamp(T/.6, 0., 1.));
      float glow = exp(-y*y*2.5)*smoothstep(1., .9, s)*smoothstep(.0, .03, s)*smoothstep(1., .85, abs(y))*(1. - .3*s)*(1. + .3*exp(-s*10.));   /* brighter where it leaves the rim */
      vec3 g = vec3(.45, .18, 1.)*glow*.09;
      if (dens < .003 && glow < .003){ discard; }
      float fo = pow(max(0., 1. - s), 1.65)*vF*smoothstep(.46, .66, vD);                                               /* fades out away from the centre: almost gone at the rim */
      gl_FragColor = vec4((col*emit*dens + g)*fo, alpha*fo);
    }

layers.vertex:
attribute vec3 aO, aE; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK, vLen;
    void main(){ float u = uTime - aT; if (u < 0. || u > (aK < .5 ? 4.9 : (aK > 1.5 ? 4.1 : 0.7))){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5){ float S = 3.8; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(vP.x, .03, -vP.y), 1.); return; }
      if (aK > 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.35 + .05*sin(uTime*1.3), 0.), 1.);   /* the orb, floating above the centre */
        float S = 1.05*(1. - pow(1. - clamp(u/.3, 0., 1.), 3.))*(1. + .18*smoothstep(3.4, 3.8, u))*(1. - smoothstep(3.8, 4.0, u));   /* swells, then implodes into the pulse */
        mv.xy += position.xy*S; vP = position.xy; gl_Position = projectionMatrix*mv; return; }
      vec3 d = aO - aE; float L = length(d); vec3 dir = d/L, side = vec3(-dir.z, 0., dir.x);
      float s = position.x*.5 + .5; vP = vec2(s, position.y); vLen = L;
      gl_Position = projectionMatrix*viewMatrix*vec4(aE + dir*s*L + side*position.y*.3 + vec3(0., .04, 0.), 1.); }

