constants.VCOMMON:
attribute vec3 aO, aB, aS; attribute float aT; attribute vec4 aP; attribute vec2 aC;
uniform float uTime, uMode; varying float vS, vHead, vBark, vKind;
vec3 vine(float s, vec4 P, float sway){
