  float tt = uTime*1.7 + P.w*11.;                                            // writhing: a wave travels up the vine
  vec3 w = vec3(.09*sin(s*7. + P.w*9.) + .05*sin(s*17. + P.w*23.) + .025*sin(s*37. + P.w*5.), 0.,
                .09*cos(s*6. + P.w*13.) + .05*sin(s*19. + P.w*7.) + .025*cos(s*41. + P.w*3.))*s
         + vec3(sin(s*4. - tt), 0., cos(s*3.5 - tt*.9))*.16*s*s;
  return vec3(cos(a)*r, h, sin(a)*r) + vec3(cos(P.x), 0., sin(P.x))*(.35*s*s) + w;
