vec3 root(float s){ vec3 S0 = vec3(aS.x, 0., aS.z), d = aB - S0, n = normalize(vec3(-d.z, 0., d.x));
  float e = sin(3.14159*s), L = length(d);                                   // irregular, wandering path (a few octaves)
  return mix(S0, aB, s) + n*e*(aC.x + L*(.07*sin(s*7. + aC.x*9.) + .045*sin(s*17. + aC.x*23.) + .025*sin(s*37. + aC.x*5.))); }
float emerge(float u){ return 1. - pow(1. - clamp(u/${EMERGE.toFixed(2)}, 0., 1.), 3.); }
float sinkT(float u, float end){ return clamp((uTime - aS.y)/${RETRACT.toFixed(2)}, 0., 1.); }   // aS.y = absolute end of the field
vec3 gP, gN; float gAlive;

constants.VBODY:
float u = uTime - aT; gAlive = u >= 0. && u <= ${LIFE.toFixed(2)} ? 1. : 0.;
vHead = 2.; vBark = 0.; vKind = uMode; vS = 0.;
if (uMode < 2.5 && uMode != 1.){                                        // thick vine body / thorn: rises out of the ground, sinks back
  float g = emerge(u), k = sinkT(u, 0.);
  float sway = sin(uTime*1.3 + aP.w*6.)*.35;
  float s = uMode < .5 ? position.y + .5 : aP.w;
  vec3 C = vine(s, aP, sway), T = normalize(vine(min(s + .01, 1.), aP, sway) - vine(max(s - .01, 0.), aP, sway));
  vec3 B = normalize(cross(T, vec3(.3, 0., 1.))), Nn = cross(B, T);
  float rad = mix(.075, .012, pow(s, .8));
  vec3 drop = vec3(0., -(1. - g)*(aP.y*1.05 + .2), 0.);                     // below the ground until it breaks out
  vHead = 1. - k;                                                           // despawn: dissolves from the tip down to the ground
  if (uMode < .5){ float ang = atan(position.z, position.x); vec3 rn = B*cos(ang) + Nn*sin(ang);
    float knot = 1. + .17*sin(s*23. + aP.w*5.) + .055*sin(ang*5. + s*61.);                                // same bark as the ground roots               // knotty, uneven bark
    gP = aO + aB + C + rn*rad*knot + drop; gN = rn; vS = s; vBark = ang; }
  else { float ang = aP.w*40.; vec3 dir = normalize(B*cos(ang) + Nn*sin(ang)), sd = normalize(cross(dir, T));
    vec3 q = position*(1.1 - .6*s);
    gP = aO + aB + C + dir*rad*.85 + dir*q.y + T*q.x*1.4 + sd*q.z + drop; gN = normalize(dir*.3 + T*position.x + sd*position.z); vS = s; vBark = 50.; }
} else if (uMode < 1.5){                                                  // ground root: creeps from the soil ring to the vine base
  float s = position.y + .5; vec3 C = root(s), T = normalize(root(min(s + .01, 1.)) - root(max(s - .01, 0.)));
  vec3 up = vec3(0., 1., 0.), B = normalize(cross(T, up)), Nn = cross(B, T);
  float ang = atan(position.z, position.x), rad = aC.y*(.55 + .45*s)*(1. + .1*sin(s*31. + aC.x*5.));
  vec3 rn = B*cos(ang) + Nn*sin(ang);
  float k = sinkT(u, 0.);
  gP = aO + C + rn*rad + vec3(0., rad*.2 - k*rad*2.5, 0.);                 // half-buried in the soil
  gN = rn; vS = s; vBark = ang; vHead = 1. - pow(1. - clamp(u/${CREEP.toFixed(2)}, 0., 1.), 2.);
} else if (uMode < 3.5){                                                  // leaf on the thick vine: opens once the vine is out
  float g = emerge(u), k = sinkT(u, 0.), sway = sin(uTime*.6 + aP.w*6.)*.08;
  float s = aP.w; vec3 C = vine(s, aP, sway), T = normalize(vine(min(s + .01, 1.), aP, sway) - vine(max(s - .01, 0.), aP, sway));
  float ang = aC.x, rad = mix(.15, .022, pow(s, .9));
  vec3 B = normalize(cross(T, vec3(.3, 0., 1.))), Nn = cross(B, T), dir = normalize(B*cos(ang) + Nn*sin(ang));
  vec3 lx = normalize(dir + T*.7 + vec3(0., .25, 0.)), ly = normalize(cross(lx, T));
  float sc = smoothstep(.55, 1., g)*(1. - k)*aC.y;
  float flutter = sin(uTime*1.3 + aP.w*20.)*.08*position.x;
  gP = aO + aB + C + dir*rad*.8 + (lx*position.x + ly*position.y + cross(lx, ly)*flutter)*sc + vec3(0., -(1. - g + k)*(aP.y*1.05 + .2), 0.);
  gN = normalize(cross(lx, ly)); vS = position.x; vBark = -10.;
} else {                                                                  // dirt clod: thrown out where the vine breaks the soil
  float t = max(u, 0.); vec3 v = aP.xyz;
  vec3 c = aB + v*t + vec3(0., -9.8*.5*t*t, 0.);
  float land = c.y < 0. ? 1. : 0.; c.y = max(c.y, .03);
  float sc = aP.w*(1. - smoothstep(.9, 1.4, t));
  gP = aO + c + position*sc; gN = normal; vBark = -20.; vS = 0.;
  gAlive *= step(t, 1.4);
}

