      float n1 = vn(vP*2.2), n2 = vn(vP*7.), Rr = R*open*(.97 + .05*vn(vec2(a*3., 1.)));
      float inside = smoothstep(Rr + .05, Rr - .3, r + (n1 - .5)*.3);
      float rim = smoothstep(.3, .0, abs(r - Rr + (n1 - .5)*.2))*smoothstep(.35, .65, n2)*.8;      // churned dirt at the limit
      float crack = smoothstep(.035, .0, abs(vn(vP*1.4 + 3.) - .5))*inside;
