    }

layers.fragment:
uniform vec3 uGold, uMoon; varying vec3 vN, vV;
    void main(){ vec3 n = normalize(vN); float l = .18 + .7*max(dot(n, uMoon), 0.), rim = pow(1. - abs(dot(n, normalize(vV))), 3.);
      gl_FragColor = vec4(mix(vec3(.62, .6, .6), uGold, .55)*l*.7 + uGold*(.25 + rim*1.4), 1.); }   // arrow in the DoT colour

layers.vertex:
attribute vec3 aO, aE; attribute float aT; attribute vec2 aA; uniform float uTime; varying float vS, vY, vF;
    vec3 path(float s){ return mix(aO, aE, s) + vec3(0., 4.*aA.x*s*(1. - s), 0.); }
    void main(){
      float u = uTime - aT - 0.1, L = length(aE - aO), tt = L/30;
      if (u < 0. || u > tt + .2){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float head = min(u/tt, 1.), tail = max(0., head - 1.2*aA.y/L) + max(0., u - tt)/.2*1.7*aA.y/L;   // after the hit, the tail catches up
      if (head - tail < .002){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = position.x*.5 + .5, p = mix(tail, head - .22*aA.y/L, s);
      vec3 P = path(p), d = normalize(aE - aO + vec3(0., 4.*aA.x*(1. - 2.*p), 0.));
      vec3 side = normalize(cross(d, P - cameraPosition));
      vS = s; vY = position.y; vF = 1. - clamp((u - tt)/.2, 0., 1.);
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*.03*aA.y, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vF;
    void main(){ float a = pow(vS, 1.6)*exp(-vY*vY*5.), c = pow(vS, 3.)*exp(-vY*vY*30.);
      vec3 o = (mix(uOrange, uGold, .3*vS)*a*.6 + mix(uOrange, uGold, .6)*c*.4)*vF;   // trail in the DoT colour
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO; attribute float aT, aR, aY; uniform float uTime; varying vec2 vL; varying float vH, vF, vP;
    void main(){ float u = uTime - aT; if (u < 0. || uTime - aR > .15){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float hold = min(u, aR - aT); vH = clamp(hold/1.2, 0., 1.);
      vF = (1. - smoothstep(0., .15, uTime - aR))*smoothstep(0., .08, u);
      vP = hold >= 1.2 ? max(0., 1. - (hold - 1.2)/.25) : 0.;           // one blink when fully shaped
      vec2 q = position.xy*19.; float c = cos(aY), s = sin(aY);
      vL = vec2(q.x, q.y);                                                     // local: x right, y forward
      vec3 W = aO + vec3(q.x*c - q.y*s, .03, -q.x*s - q.y*c);
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.); }

layers.fragment:
uniform vec3 uDot, uDotL; varying vec2 vL; varying float vH, vF, vP;
    void main(){
      float r = length(vL), a = atan(vL.x, vL.y), A = mix(.44, 0., vH), R = mix(9., 18., vH);
      float near = smoothstep(.6, 1.6, r), inR = smoothstep(R + .05, R - .05, r), inA = smoothstep(A + .01, A - .01, abs(a));
      float edge = exp(-pow((abs(a) - A)*r/mix(.05, .08, vH*vH), 2.))*inR*near*(1. + .6*vH*vH);   // the two borders (one line at the end)
      float arc = exp(-pow((r - R)/.06, 2.))*inA;                              // the range line
      float fill = inA*inR*near*smoothstep(R*.35, R, r)*.07;                   // faint, open centre
      float lum = (edge*.55 + arc*.45 + fill)*(.7 + .3*vH)*(1. + 1.5*vP);
      vec3 o = mix(uDot, uDotL, .25)*lum*vF*.8;
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO; attribute float aT, aS; uniform float uTime; varying vec2 vP; varying float vU, vS;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.18){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aO, 1.); mv.xyz += normalize(-mv.xyz)*.3; mv.xy += position.xy*.42;
      vP = position.xy*.42; vU = u; vS = aS; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uDot, uDotL; varying vec2 vP; varying float vU, vS;
    void main(){
      vec2 p = vP; float lum = 0., hot = 0.;
        float t = vU/0.18, f = pow(1. - t, 1.4)*(vU < .033 ? 1.7 : 1.), r = length(p), a = atan(p.y, p.x);
        float k = 1. - pow(1. - clamp(t/.6, 0., 1.), 3.);
        lum += exp(-r*r*(90. + 400.*t))*f*1.3;                                   // splat core
        for (int j = 0; j < 8; j++){
          float fj = float(j), h = fract(sin(fj*71.3 + vS*13.)*4375.5), aj = fj*.785 + h*.6;
          vec2 dir = vec2(cos(aj), sin(aj)); float Rj = (.12 + .2*h)*k;           // each droplet flies its own distance
          vec2 q = p - dir*Rj; float sz = (.018 + .014*fract(h*7.))*(1. - .6*t);
          float al = dot(q, dir), ac = dot(q, vec2(-dir.y, dir.x));
          lum += exp(-(ac*ac)/(sz*sz) - (al*al)/(sz*sz*4.))*f;                  // stretched along its motion
        }
        hot = lum*.45;
      vec3 o = (uDot*lum + mix(uDot, uDotL, .7)*hot)*smoothstep(.42, .34, length(p));
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.); }

constants.RCOMMON:
attribute vec4 aA, aP, aK, aT; uniform float uTime; varying float vS, vHead, vBark, vLeaf;
vec3 Wr(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return aA.xyz + vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
vec3 WDr(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
float snapE, openR;
vec3 coil(float s){                                            // one coil around both legs together, wide → tight on the snap
  float a = aP.x + s*aP.y*6.2832 + (1. - snapE)*1.2, R = (.23 - .05*s)*(1. + 1.4*(1. - snapE))*openR;
  vec3 wob = vec3(.008*sin(s*23. + aP.w*9.), 0., .008*cos(s*19. + aP.w*5.));
  return vec3(.12*aK.x, 0., -.02) + vec3(cos(a)*R, s*aP.z, sin(a)*R) + wob;
}
vec3 gP, gN; float gAlive;

constants.RBODY:
float u = uTime - aT.x, te = uTime - aT.y, rt = uTime - aT.z;
float rdur = aT.w > 2.5 ? .12 : .2;
gAlive = (u >= 0. && te < .3 && rt < rdur) ? 1. : 0.;
snapE = 1. - pow(1. - clamp(u/.12, 0., 1.), 3.);
float brk = (rt > 0. && aT.w > 1.5 && aT.w < 2.5) ? clamp(rt/rdur, 0., 1.) : 0.;
openR = 1. + 1.5*brk;                                          // Cleanse: the coil bursts open
float gone = max(clamp(te/.3, 0., 1.), rt > 0. ? clamp(rt/rdur, 0., 1.) : 0.);
vHead = min(snapE*1.05, 1. - gone);                            // grows up in the snap; dissolves top-down when it ends
vLeaf = 0.;
if (aK.y < 0.){                                                // vine tube
  float s = position.y + .5; vec3 C = coil(s), T = normalize(coil(min(s + .01, 1.)) - coil(max(s - .01, 0.)));
  vec3 B = normalize(cross(T, vec3(0., 1., 0.))), Nn = cross(B, T);
  float ang = atan(position.z, position.x), rad = mix(.028, .01, s)*(1. + .12*sin(s*31. + aP.w*5.));
  vec3 rn = B*cos(ang) + Nn*sin(ang);
  gP = Wr(C + rn*rad); gN = WDr(rn); vS = s; vBark = ang;
} else {                                                       // leaf opening on the vine
  float s = aK.y; vec3 C = coil(s), T = normalize(coil(min(s + .01, 1.)) - coil(max(s - .01, 0.)));
  vec3 ow = normalize(C - vec3(.12*aK.x, C.y, -.02)), lx = normalize(ow + T*.6 + vec3(0., .3, 0.)), ly = normalize(cross(lx, T));
  float sc = .09*smoothstep(.5, 1., snapE)*(1. - gone), fl = sin(uTime*1.3 + aP.w*20.)*.08*position.x;
  gP = Wr(C + ow*.015 + (lx*position.x + ly*position.y + cross(lx, ly)*fl)*sc); gN = WDr(normalize(cross(lx, ly))); vS = aK.y; vBark = -10.; vLeaf = 1.;
}

layers.vertex:
attribute vec4 aA, aK, aT; attribute vec3 aC; uniform float uTime;
    varying vec2 vQ; varying float vK, vLum, vTaper, vSeed, vFace; varying vec3 vCol;
    vec3 W(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return aA.xyz + vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
    vec3 WD(vec3 l){ float c = cos(aA.w), s = sin(aA.w); return vec3(c*l.x + s*l.z, l.y, -s*l.x + c*l.z); }
    float eo3(float x){ x = clamp(x, 0., 1.); return 1. - pow(1. - x, 3.); }
    void main(){
      float kind = aK.x, age = uTime - aT.x, te = uTime - aT.y, rt = uTime - aT.z, why = aT.w;
      float rdur = why > 2.5 ? .12 : .2;
      if (age < 0. || te > .3 || rt > rdur){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float endk = clamp(te/.3, 0., 1.), rp = rt < 0. ? 0. : rt/rdur, cl = (why > 1.5 && why < 2.5) ? eo3(rp) : 0.;
      float grow = eo3(age/.15), fade = (1. - endk)*(1. - rp)*(age < .033 ? 1.6 : 1.);
      float s = position.x + .5, y = position.y*2.;
      vQ = vec2(s, y); vK = kind; vCol = aC; vSeed = 0.; vFace = 1.; vTaper = 1.;
      vec3 Pw, Tw; float Wd = .02, lum = fade, taper = 1.;

      if (kind < 1.5){
        // STUN: small 4-point star on a horizontal orbit around the head, outside the Sleep bubble
        float a = uTime*2.2 + aK.y*1.0472, R = .33*mix(.3, 1., grow)*(1. + .7*cl)*(1. - .5*endk);
        vec3 P = vec3(cos(a)*R, 1.8 + .025*sin(a*2. + aK.y), sin(a)*R);
        vec4 mv = viewMatrix*vec4(W(P), 1.);
        mv.xy += position.xy*2.*.07*(1. - .4*endk);
        vQ = position.xy*2.; vSeed = uTime*3. + aK.y; vLum = fade*(.9 + .2*sin(uTime*6. + aK.y*2.));
        gl_Position = projectionMatrix*mv; return;
